exercise.starter:
import * as fs from "fs";
const raw = fs.readFileSync(0, "utf8").trim();
____

exercise.solution:
import * as fs from "fs";
const raw = fs.readFileSync(0, "utf8").trim();
const colon = raw.indexOf(":");
const words = raw.slice(0, colon).replaceAll("-", " ").toLowerCase();
const label = words[0].toUpperCase() + words.slice(1);
const code = label.slice(0, 3).toUpperCase();
const amount = parseInt(raw.slice(colon + 1), 10);
console.log(`Label:  ${label}`);
console.log(`Code:   ${code}`);
console.log(`Amount: ${amount}`);
console.log(`Row:    ${label.padEnd(22, ".")} ${amount}`);

