exercise.solution:
import * as fs from "fs";
const raw = fs.readFileSync(0, "utf8").trim();
const n = Number(raw);
if (!raw) {
  console.log("Invalid: no amount");
  console.log("Band:    -");
} else if (Number.isNaN(n)) {
  console.log("Invalid: not a number");
  console.log("Band:    -");
} else if (n < 0) {
  console.log("Invalid: negative");
  console.log("Band:    -");
} else {
  console.log(`Amount:  ${n.toFixed(2)}`);
  console.log(`Band:    ${n < 10 ? "small" : n < 50 ? "medium" : "large"}`);
}

